1	import React, { useEffect, useState, useRef, useLayoutEffect } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import styles from './SpaceTransitionOverlay.module.scss';
4	
5	/**
6	 * Rideau plein écran joué à chaque changement d'espace (Préparation / Prévisualisation /
7	 * Modélisation / Dev), en 4 étapes STRICTEMENT séquentielles (le flou est entièrement terminé
8	 * avant que le voile ne commence à apparaître — jamais les deux à la fois) :
9	 *   1. blur    — flou de l'interface, sans aucune teinte de couleur.
10	 *   2. paint   — une fois le flou installé, le voile bleu opaque est « peint » par grosses tuiles
11	 *                (grille TILE_COLS × TILE_ROWS), chacune apparaissant avec un délai croissant
12	 *                selon sa distance au coin haut-droit, façon touches de pinceau qui balaient
13	 *                l'écran en diagonale vers le coin bas-gauche.
14	 *   3. text    — le texte apparaît une fois toutes les tuiles posées ("APEX" en Ethnocentric, le
15	 *                nom de l'espace en Orbitron) ; c'est aussi à ce moment que le switch réel a lieu.
16	 *   4. fadeout — même effet de tuiles que l'apparition, rejoué à l'identique (mêmes délais, même
17	 *                balayage diagonal) mais en disparition ; le flou se dissipe en même temps,
18	 *                révélant le nouvel espace.
19	 *
20	 * Piloté par l'événement `apex-space-transition` (voir Sidebar.tsx, seul émetteur) plutôt qu'un
21	 * state React partagé, pour rester cohérent avec le bus d'événements global du reste de l'app
22	 * (cf. CLAUDE.md).
23	 */
24	
25	const BLUR_MS = 320;      // 1. montée du flou seul, doit être TERMINÉE avant la moindre tuile
26	// Tuiles 3× plus petites (en aire) que la grille précédente (8×5) : même ratio, dimensions
27	// multipliées par √3.
28	const TILE_COLS = 14;
29	const TILE_ROWS = 9;
30	// Réduit par rapport à la grille précédente (8×5, pas 28ms) pour garder une durée de balayage
31	// comparable malgré la diagonale plus longue (14+9 vs 8+5 pas).
32	const TILE_STEP_MS = 15;  // délai entre deux tuiles consécutives dans l'ordre de balayage
33	const TILE_ANIM_MS = 260; // durée d'apparition d'une tuile individuelle
34	// Le dernier délai + sa propre durée d'anim = durée totale de la phase "paint".
35	const PAINT_MS = (TILE_COLS + TILE_ROWS - 2) * TILE_STEP_MS + TILE_ANIM_MS;
36	const TEXT_MS = 420 * 3;  // 3. texte affiché, voile plein écran (switch réel ici)
37	const FADEOUT_MS = PAINT_MS; // 4. même effet de tuiles que l'apparition, même durée totale
38	const TOTAL_MS = BLUR_MS + PAINT_MS + TEXT_MS + FADEOUT_MS;
39	
40	type Phase = 'blur' | 'paint' | 'text' | 'fadeout';
41	
42	interface SpaceTransitionDetail {
43	  label: string;
44	  onCovered?: () => void;
45	}
46	
47	// Grille de tuiles avec leur délai de balayage : distance (en pas de grille) au coin haut-droit,
48	// donc la tuile (col=COLS-1, row=0) part la première et (col=0, row=ROWS-1) la dernière — un
49	// vrai balayage diagonal plutôt qu'un simple décalage ligne par ligne.
50	const TILES = Array.from({ length: TILE_COLS * TILE_ROWS }, (_, i) => {
51	  const col = i % TILE_COLS;
52	  const row = Math.floor(i / TILE_COLS);
53	  const distance = (TILE_COLS - 1 - col) + row;
54	  return { col, row, delayMs: distance * TILE_STEP_MS };
55	});
56	
57	// Largeur cible (en px) que le nom de l'espace doit occuper, quel que soit le nombre de
58	// lettres — c'est ce qui fait que "DEV" et "PRÉVISUALISATION" remplissent tous les deux le
59	// même cadre plutôt que d'avoir un espacement de lettres fixe (donc une largeur qui varie
60	// avec la longueur du mot).
61	const SPACE_NAME_TARGET_WIDTH_PX = 260;
62	
63	export const SpaceTransitionOverlay: React.FC = () => {
64	  const [label, setLabel] = useState<string | null>(null);
65	  const [phase, setPhase] = useState<Phase>('blur');
66	  const timeoutsRef = useRef<number[]>([]);
67	  // Change à chaque déclenchement pour forcer framer-motion à rejouer l'apparition des tuiles
68	  // (sans clé, une 2e transition juste après la 1re les laisserait déjà toutes posées).
69	  const [runId, setRunId] = useState(0);
70	  const spaceNameRef = useRef<HTMLSpanElement>(null);
71	  // Espacement de lettres recalculé pour chaque `label` afin que le texte remplisse toujours
72	  // SPACE_NAME_TARGET_WIDTH_PX, au lieu d'un `letter-spacing` fixe qui laisse un mot court
73	  // (« Dev ») loin de remplir le cadre et un mot long (« Prévisualisation ») le déborder.
74	  const [spaceNameLetterSpacing, setSpaceNameLetterSpacing] = useState(0.5);
75	  const painted = phase === 'text' || phase === 'fadeout';
76	
77	  useLayoutEffect(() => {
78	    const el = spaceNameRef.current;
79	    if (!label || !el) return;
80	
81	    // Mesure la largeur du texte SANS espacement de lettres ajouté, pour en déduire combien
82	    // en ajouter par intervalle afin d'atteindre la largeur cible.
83	    el.style.letterSpacing = '0px';
84	    const naturalWidth = el.getBoundingClientRect().width;
85	    const gapCount = Math.max(label.length - 1, 1);
86	    const extraPx = Math.max(SPACE_NAME_TARGET_WIDTH_PX - naturalWidth, 0);
87	    const fontSize = parseFloat(getComputedStyle(el).fontSize) || 15;
88	    const spacingEm = extraPx / gapCount / fontSize;
89	
90	    setSpaceNameLetterSpacing(spacingEm);
91	    // Dépend aussi de `painted` : le <span> n'existe dans le DOM qu'une fois les tuiles posées
92	    // (rendu conditionnel plus bas), donc au moment où `label` change seul le ref est encore
93	    // null — il faut remesurer une fois le nœud monté.
94	  }, [label, painted]);
95	
96	  useEffect(() => {
97	    const clearTimeouts = () => {
98	      timeoutsRef.current.forEach((id) => window.clearTimeout(id));
99	      timeoutsRef.current = [];
100	    };
101	
102	    const handleTransition = (e: Event) => {
103	      const detail = (e as CustomEvent<SpaceTransitionDetail>).detail;
104	      if (!detail?.label) return;
105	
106	      clearTimeouts();
107	      setLabel(detail.label);
108	      setPhase('blur');
109	      setRunId((id) => id + 1);
110	
111	      timeoutsRef.current.push(
112	        window.setTimeout(() => setPhase('paint'), BLUR_MS),
113	        window.setTimeout(() => {
114	          // Le contenu change une fois toutes les tuiles posées, jamais visible.
115	          detail.onCovered?.();
116	          setPhase('text');
117	        }, BLUR_MS + PAINT_MS),
118	        window.setTimeout(() => setPhase('fadeout'), BLUR_MS + PAINT_MS + TEXT_MS),
119	        window.setTimeout(() => setLabel(null), TOTAL_MS),
120	      );
121	    };
122	
123	    window.addEventListener('apex-space-transition', handleTransition);
124	    return () => {
125	      window.removeEventListener('apex-space-transition', handleTransition);
126	      clearTimeouts();
127	    };
128	  }, []);
129	
130	  const fadingOut = phase === 'fadeout';
131	
132	  return (
133	    <AnimatePresence>
134	      {label && (
135	        <div className={styles.overlay}>
136	          {/* Étape 1 : flou seul, sans teinte — entièrement monté avant la moindre tuile. */}
137	          <motion.div
138	            className={styles.blurLayer}
139	            initial={{ backdropFilter: 'blur(0px)' }}
140	            animate={{ backdropFilter: fadingOut ? 'blur(0px)' : 'blur(18px)' }}
141	            transition={{ duration: (fadingOut ? FADEOUT_MS : BLUR_MS) / 1000, ease: [0.4, 0, 0.2, 1] }}
142	          />
143	
144	          {/* Étape 2 (paint) / 4 (fadeout) : mêmes tuiles, même balayage et mêmes délais dans les
145	              deux sens — seule la cible (posée vs. retirée) change avec `fadingOut`. */}
146	          <div className={styles.tileGrid}>
147	            {phase !== 'blur' && TILES.map(({ col, row, delayMs }) => (
148	              <motion.div
149	                key={`${runId}-${col}-${row}`}
150	                className={styles.tile}
151	                style={{
152	                  left: `${(col / TILE_COLS) * 100}%`,
153	                  top: `${(row / TILE_ROWS) * 100}%`,
154	                  width: `${100 / TILE_COLS}%`,
155	                  height: `${100 / TILE_ROWS}%`,
156	                }}
157	                initial={{ opacity: 0, scale: 1.3 }}
158	                animate={fadingOut ? { opacity: 0, scale: 1.3 } : { opacity: 1, scale: 1 }}
159	                transition={{ duration: TILE_ANIM_MS / 1000, delay: delayMs / 1000, ease: [0.16, 1, 0.3, 1] }}
160	              />
161	            ))}
162	          </div>
163	
164	          <AnimatePresence>
165	            {painted && (
166	              <motion.div
167	                className={styles.textBlock}
168	                initial={{ opacity: 0, scale: 0.85, letterSpacing: '0.4em' }}
169	                animate={{ opacity: fadingOut ? 0 : 1, scale: 1, letterSpacing: '0.15em' }}
170	                exit={{ opacity: 0, scale: 1.08, letterSpacing: '0.5em' }}
171	                transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
172	              >
173	                <span className={styles.brand}>APEX</span>
174	                <span
175	                  ref={spaceNameRef}
176	                  className={styles.spaceName}
177	                  style={{ letterSpacing: `${spaceNameLetterSpacing}em` }}
178	                >
179	                  {label}
180	                </span>
181	                <motion.span
182	                  className={styles.scanline}
183	                  initial={{ scaleX: 0, opacity: 0.9 }}
184	                  animate={{ scaleX: 1, opacity: 0 }}
185	                  transition={{ duration: 0.5, ease: 'easeOut' }}
186	                />
187	              </motion.div>
188	            )}
189	          </AnimatePresence>
190	        </div>
191	      )}
192	    </AnimatePresence>
193	  );
194	};
