1	// `absolute` (et non `fixed`) : borné au bloc `main` qui l'accueille (voir Index.tsx), donc au
2	// seul espace 3D — les panneaux en superposition (sidebars, menus, tooltips), tous en
3	// `position: fixed` avec un z-index ≥ 1000, forment leur propre contexte d'empilement à la
4	// racine et restent ainsi visibles par-dessus, sans flou ni voile.
5	.overlay {
6	  position: absolute;
7	  inset: 0;
8	  z-index: 30;
9	  display: flex;
10	  align-items: center;
11	  justify-content: center;
12	  pointer-events: none;
13	  overflow: hidden;
14	}
15	
16	// Étape 1 : flou seul, sans aucune teinte — une simple loupe sur ce qu'il y a derrière.
17	.blurLayer {
18	  position: absolute;
19	  inset: 0;
20	  -webkit-backdrop-filter: blur(0px);
21	}
22	
23	// Étape 2 : grille de grosses tuiles peintes une à une (cf. TSX) plutôt qu'un voile continu.
24	.tileGrid {
25	  position: absolute;
26	  inset: 0;
27	}
28	
29	.tile {
30	  position: absolute;
31	  // Léger débord pour recouvrir la jointure avec les tuiles voisines (anti-aliasing/arrondis).
32	  margin: -1px;
33	  // Voile gris neutre (plus de teinte bleue) : dégradé clair → sombre, même construction
34	  // radiale qu'avant pour garder le même effet de balayage une fois toutes les tuiles posées.
35	  background:
36	    radial-gradient(140% 160% at 100% 0%, rgba(150, 152, 156, 0.9), rgba(58, 60, 66, 0.97) 55%, rgba(20, 21, 24, 1) 100%);
37	  // Chaque tuile lit le dégradé à sa propre position dans le viewport (pas re-scalé par tuile),
38	  // pour que l'ensemble reforme un dégradé continu une fois toutes les tuiles posées.
39	  background-attachment: fixed;
40	  background-size: 100vw 100vh;
41	  background-position: 0 0;
42	}
43	
44	.textBlock {
45	  position: relative;
46	  display: flex;
47	  flex-direction: column;
48	  align-items: center;
49	  gap: 14px;
50	  text-align: center;
51	}
52	
53	.brand {
54	  font-family: 'Ethnocentric', 'Orbitron', sans-serif;
55	  font-weight: 400;
56	  font-size: clamp(64px, 11vw, 160px);
57	  line-height: 1;
58	  letter-spacing: 0.05em;
59	  color: #eafcff;
60	  // Halo blanc seul, sans teinte bleue/cyan.
61	  text-shadow: 0 0 16px rgba(255, 255, 255, 0.6);
62	}
63	
64	// Petit, tout en majuscules et très espacé — le style "M O D É L I S A T I O N". L'espacement
65	// des lettres est calculé dynamiquement (voir SpaceTransitionOverlay.tsx) pour que le mot
66	// remplisse toujours la même largeur, que le nom de l'espace fasse 3 lettres ("Dev") ou 16
67	// ("Prévisualisation") — un letter-spacing fixe en em ne le permettrait pas.
68	.spaceName {
69	  font-family: 'Orbitron', sans-serif;
70	  font-weight: 600;
71	  font-size: 15px;
72	  text-transform: uppercase;
73	  color: rgba(255, 255, 255, 0.85);
74	}
75	
76	.scanline {
77	  position: absolute;
78	  left: 0;
79	  right: 0;
80	  bottom: -12px;
81	  height: 2px;
82	  background: linear-gradient(90deg, transparent, #ffffff, transparent);
83	  transform-origin: center;
84	}
