  background-position: 0 0;
}

.textBlock {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  text-align: center;
}

.brand {
  font-family: 'Ethnocentric', 'Orbitron', sans-serif;
  font-weight: 400;
  font-size: clamp(64px, 11vw, 160px);
  line-height: 1;
  letter-spacing: 0.05em;
  color: #eafcff;
